import { fireEvent, render, screen } from "@testing-library/react"
import { expect, test } from "vitest"
import { I18nProvider, useI18n } from "./i18n"

function Probe() {
  const { locale, setLocale, t } = useI18n()
  return <><p>{locale}:{t("providerProfiles")}</p><button onClick={() => setLocale("zh-CN")}>change</button></>
}

test("English and zh-CN catalogs share the product keys and persist the selected locale", () => {
  render(<I18nProvider><Probe /></I18nProvider>)
  expect(screen.getByText("en:Provider profiles")).toBeInTheDocument()
  fireEvent.click(screen.getByRole("button", { name: "change" }))
  expect(screen.getByText("zh-CN:Provider 配置")).toBeInTheDocument()
  expect(localStorage.getItem("ji.preferences.v1.locale")).toBe("zh-CN")
})
